package neural

import("context";"math";"testing")
func TestNetworkRuntime(t *testing.T){n,err:=New(3,.1);if err!=nil{t.Fatal(err)};if err=n.AddEdge(0,1,.5);err!=nil{t.Fatal(err)};if _,err=n.Forward(context.Background(),[]float64{1,0,0});err!=nil{t.Fatal(err)};if err=n.Learn([]float64{1,0,0},[]float64{0,1,0});err!=nil{t.Fatal(err)};if _,err=n.Normalize([]float64{1,2,3});err!=nil{t.Fatal(err)};if _,err=n.Attention([]float64{1},[]float64{1,2},[]float64{3,4});err!=nil{t.Fatal(err)};if _,err=n.Backprop([]float64{1,2,3},[]float64{0,1,0});err!=nil{t.Fatal(err)};if err=n.RemoveEdge(0,1);err!=nil{t.Fatal(err)};if n.Health()["status"]!="ready"{t.Fatal("network unhealthy")}}
func TestNetworkRejectsNonFiniteAndMalformedAttention(t *testing.T){n,_:=New(2,.1);if _,err:=n.Forward(context.Background(),[]float64{math.NaN(),0});err==nil{t.Fatal("NaN accepted")};if _,err:=n.Attention(nil,[]float64{1},[]float64{1});err==nil{t.Fatal("empty query accepted")};if _,err:=n.Attention([]float64{1},[]float64{1,2},[]float64{1});err==nil{t.Fatal("mismatched attention vectors accepted")}}
func TestNilNetworkPublicPaths(t *testing.T){var n *Network;if _,err:=n.AddEdge(0,1,.1);err==nil{t.Fatal("nil AddEdge accepted")};if _,err:=n.RemoveEdge(0,1);err==nil{t.Fatal("nil RemoveEdge accepted")};if _,err:=n.Activate([]float64{1});err==nil{t.Fatal("nil Activate accepted")};if _,err:=n.Forward(context.Background(),[]float64{1});err==nil{t.Fatal("nil Forward accepted")};if err:=n.Learn([]float64{1},[]float64{1});err==nil{t.Fatal("nil Learn accepted")};if _,err:=n.Normalize([]float64{1});err==nil{t.Fatal("nil Normalize accepted")};if _,err:=n.Attention([]float64{1},[]float64{1},[]float64{1});err==nil{t.Fatal("nil Attention accepted")};if _,err:=n.Backprop([]float64{1},[]float64{1});err==nil{t.Fatal("nil Backprop accepted")};if n.Health()["status"]!="unavailable"{t.Fatal("nil network health incorrect")}}
func TestLearnChangesObservableOutput(t *testing.T){n,err:=New(2,.05);if err!=nil{t.Fatal(err)};before,err:=n.Forward(context.Background(),[]float64{1,0});if err!=nil{t.Fatal(err)};for i:=0;i<5;i++{if err:=n.Learn([]float64{1,0},[]float64{1,1});err!=nil{t.Fatal(err)}};after,err:=n.Forward(context.Background(),[]float64{1,0});if err!=nil{t.Fatal(err)};if before[1]==after[1]&&before[0]==after[0]{t.Fatalf("learning produced no observable change: before=%v after=%v",before,after)}}
